import java.util.ArrayList;
import java.util.List;

class Solution {
    private static final int NULL_TOKEN = Integer.MIN_VALUE;

    public boolean isSubtree(TreeNode root, TreeNode subRoot) {
        List<Integer> text = new ArrayList<>();
        List<Integer> pattern = new ArrayList<>();
        serialize(root, text);
        serialize(subRoot, pattern);
        int[] prefix = new int[pattern.size()];
        for (int index = 1, matched = 0; index < pattern.size();) {
            if (pattern.get(index).equals(pattern.get(matched))) {
                prefix[index++] = ++matched;
            } else if (matched > 0) {
                matched = prefix[matched - 1];
            } else {
                index++;
            }
        }
        for (int index = 0, matched = 0; index < text.size();) {
            if (text.get(index).equals(pattern.get(matched))) {
                index++;
                matched++;
                if (matched == pattern.size()) return true;
            } else if (matched > 0) {
                matched = prefix[matched - 1];
            } else {
                index++;
            }
        }
        return false;
    }

    private void serialize(TreeNode node, List<Integer> output) {
        if (node == null) {
            output.add(NULL_TOKEN);
            return;
        }
        output.add(node.val);
        serialize(node.left, output);
        serialize(node.right, output);
    }
}
